     1→import "@shopify/shopify-app-react-router/adapters/node";
     2→import {
     3→  ApiVersion,
     4→  AppDistribution,
     5→  BillingInterval,
     6→  shopifyApp,
     7→} from "@shopify/shopify-app-react-router/server";
     8→// ApiVersion.January26 = "2026-01" — matches shopify.app.toml
     9→import { PrismaSessionStorage } from "@shopify/shopify-app-session-storage-prisma";
    10→import prisma from "./db.server";
    11→import {
    12→  PLAN_PRO_MONTHLY,
    13→  PLAN_PRO_ANNUAL,
    14→  PLAN_ULTIMATE_MONTHLY,
    15→  PLAN_ULTIMATE_ANNUAL,
    16→} from "./plans";
    17→
    18→// Re-export plan helpers so server code can import from one place
    19→export {
    20→  PLAN_FREE,
    21→  PLAN_PRO_MONTHLY,
    22→  PLAN_PRO_ANNUAL,
    23→  PLAN_ULTIMATE_MONTHLY,
    24→  PLAN_ULTIMATE_ANNUAL,
    25→  ALL_PAID_PLANS,
    26→  PLAN_LIMITS,
    27→  getPlanTier,
    28→} from "./plans";
    29→
    30→const shopify = shopifyApp({
    31→  apiKey: process.env.SHOPIFY_API_KEY,
    32→  apiSecretKey: process.env.SHOPIFY_API_SECRET || "",
    33→  apiVersion: ApiVersion.January26,
    34→  scopes: process.env.SCOPES?.split(","),
    35→  appUrl: process.env.SHOPIFY_APP_URL || "",
    36→  authPathPrefix: "/auth",
    37→  sessionStorage: new PrismaSessionStorage(prisma),
    38→  distribution: AppDistribution.AppStore,
    39→  future: {
    40→    expiringOfflineAccessTokens: true,
    41→  },
    42→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
    43→  billing: {
    44→    [PLAN_PRO_MONTHLY]: {
    45→      amount: 12.99,
    46→      currencyCode: "USD",
    47→      interval: BillingInterval.Every30Days,
    48→      trialDays: 14,
    49→    },
    50→    [PLAN_PRO_ANNUAL]: {
    51→      amount: 99.0,
    52→      currencyCode: "USD",
    53→      interval: BillingInterval.Annual,
    54→      trialDays: 14,
    55→    },
    56→    [PLAN_ULTIMATE_MONTHLY]: {
    57→      amount: 24.99,
    58→      currencyCode: "USD",
    59→      interval: BillingInterval.Every30Days,
    60→      trialDays: 14,
    61→    },
    62→    [PLAN_ULTIMATE_ANNUAL]: {
    63→      amount: 199.0,
    64→      currencyCode: "USD",
    65→      interval: BillingInterval.Annual,
    66→      trialDays: 14,
    67→    },
    68→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
    69→  } as any,
    70→  ...(process.env.SHOP_CUSTOM_DOMAIN
    71→    ? { customShopDomains: [process.env.SHOP_CUSTOM_DOMAIN] }
    72→    : {}),
    73→});
    74→
    75→export default shopify;
    76→export const apiVersion = ApiVersion.January26;
    77→export const addDocumentResponseHeaders = shopify.addDocumentResponseHeaders;
    78→export const authenticate = shopify.authenticate;
    79→export const unauthenticated = shopify.unauthenticated;
    80→export const login = shopify.login;
    81→export const registerWebhooks = shopify.registerWebhooks;
    82→export const sessionStorage = shopify.sessionStorage;
