     1→import { useState, useEffect, useCallback } from "react";
     2→import type {
     3→  ActionFunctionArgs,
     4→  HeadersFunction,
     5→  LoaderFunctionArgs,
     6→} from "react-router";
     7→import { useFetcher, useLoaderData } from "react-router";
     8→import { useAppBridge } from "@shopify/app-bridge-react";
     9→import { boundary } from "@shopify/shopify-app-react-router/server";
    10→import { authenticate } from "../shopify.server";
    11→import {
    12→  ALL_PAID_PLANS,
    13→  PLAN_PRO_MONTHLY,
    14→  PLAN_PRO_ANNUAL,
    15→  PLAN_ULTIMATE_MONTHLY,
    16→  PLAN_ULTIMATE_ANNUAL,
    17→} from "../plans";
    18→import {
    19→  syncSubscriptionFromShopify,
    20→  cancelShopSubscription,
    21→  getShopSubscription,
    22→} from "../billing.server";
    23→import {
    24→  Page,
    25→  Layout,
    26→  Card,
    27→  BlockStack,
    28→  InlineStack,
    29→  Text,
    30→  Badge,
    31→  Button,
    32→  ButtonGroup,
    33→  Divider,
    34→  Box,
    35→  Banner,
    36→  Icon,
    37→  Modal,
    38→  InlineGrid,
    39→} from "@shopify/polaris";
    40→import { CheckCircleIcon, StarIcon } from "@shopify/polaris-icons";
    41→
    42→// ─── Plan data ────────────────────────────────────────────────────────────────
    43→
    44→const PLANS_DATA = {
    45→  free: {
    46→    id: "free",
    47→    name: "Free",
    48→    monthlyPrice: 0,
    49→    annualPrice: 0,
    50→    annualMonthlyPrice: 0,
    51→    description: "Perfect for new stores getting started",
    52→    features: [
    53→      "Up to 25 zip codes",
    54→      "Allowed zip codes only",
    55→      "Basic storefront widget",
    56→      "Standard email support",
    57→    ],
    58→    shopifyPlanMonthly: null as string | null,
    59→    shopifyPlanAnnual: null as string | null,
    60→  },
    61→  pro: {
    62→    id: "pro",
    63→    name: "Pro",
    64→    monthlyPrice: 12.99,
    65→    annualPrice: 99,
    66→    annualMonthlyPrice: 8.25,
    67→    description: "For growing stores that need more control",
    68→    features: [
    69→      "Unlimited zip codes",
    70→      "Allowed + Blocked zip codes",
    71→      "Delivery zones & ETAs",
    72→      "Bulk CSV import & export",
    73→      "Customer waitlist",
    74→      "Priority email support",
    75→    ],
    76→    shopifyPlanMonthly: PLAN_PRO_MONTHLY,
    77→    shopifyPlanAnnual: PLAN_PRO_ANNUAL,
    78→    bestValue: true,
    79→  },
    80→  ultimate: {
    81→    id: "ultimate",
    82→    name: "Ultimate",
    83→    monthlyPrice: 24.99,
    84→    annualPrice: 199,
    85→    annualMonthlyPrice: 16.58,
    86→    description: "For high-volume stores needing top-tier features",
    87→    features: [
    88→      "Everything in Pro",
    89→      "Advanced delivery rules",
    90→      "Customisable widget CSS",
    91→      "API access",
    92→      "24/7 VIP support",
    93→      "Early access to new features",
    94→    ],
    95→    shopifyPlanMonthly: PLAN_ULTIMATE_MONTHLY,
    96→    shopifyPlanAnnual: PLAN_ULTIMATE_ANNUAL,
    97→  },
    98→};
    99→
   100→// ─── Loader ───────────────────────────────────────────────────────────────────
   101→
   102→export const loader = async ({ request }: LoaderFunctionArgs) => {
   103→  const { session, billing } = await authenticate.admin(request);
   104→  const shop = session.shop;
   105→
   106→  try {
   107→    /* eslint-disable @typescript-eslint/no-explicit-any */
   108→    const billingCheck = await billing.check({
   109→      plans: ALL_PAID_PLANS as any,
   110→      isTest: process.env.NODE_ENV !== "production",
   111→    });
   112→    /* eslint-enable @typescript-eslint/no-explicit-any */
   113→    const subscription = await syncSubscriptionFromShopify(
   114→      shop,
   115→      billingCheck.appSubscriptions ?? [],
   116→    );
   117→    return { subscription };
   118→  } catch {
   119→    const subscription = await getShopSubscription(shop);
   120→    return { subscription };
   121→  }
   122→};
   123→
   124→// ─── Action ───────────────────────────────────────────────────────────────────
   125→
   126→export const action = async ({ request }: ActionFunctionArgs): Promise<
   127→  | { confirmationUrl: string }
   128→  | { error: string }
   129→  | { success: boolean; message: string }
   130→  | null
   131→> => {
   132→  const { session, billing } = await authenticate.admin(request);
   133→  const shop = session.shop;
   134→  const formData = await request.formData();
   135→  const intent = String(formData.get("intent"));
   136→
   137→  if (intent === "subscribe") {
   138→    const plan = String(formData.get("plan"));
   139→    const returnUrl = `${process.env.SHOPIFY_APP_URL}/app/pricing`;
   140→    try {
   141→      /* eslint-disable @typescript-eslint/no-explicit-any */
   142→      const confirmationUrl = await billing.request({
   143→        plan: plan as any,
   144→        isTest: process.env.NODE_ENV !== "production",
   145→        returnUrl,
   146→      }) as string;
   147→      /* eslint-enable @typescript-eslint/no-explicit-any */
   148→      return { confirmationUrl };
   149→    } catch {
   150→      return { error: "Failed to initiate subscription. Please try again." };
   151→    }
   152→  }
   153→
   154→  if (intent === "cancel") {
   155→    try {
   156→      const sub = await getShopSubscription(shop);
   157→      if (sub.shopifySubscriptionId) {
   158→        await billing.cancel({
   159→          subscriptionId: sub.shopifySubscriptionId,
   160→          isTest: process.env.NODE_ENV !== "production",
   161→          prorate: true,
   162→        });
   163→      }
   164→      await cancelShopSubscription(shop);
   165→      return {
   166→        success: true,
   167→        message: "Subscription cancelled. You are now on the Free plan.",
   168→      };
   169→    } catch {
   170→      return { error: "Failed to cancel subscription. Please try again." };
   171→    }
   172→  }
   173→
   174→  return null;
   175→};
   176→
   177→// ─── Feature row ─────────────────────────────────────────────────────────────
   178→
   179→function PlanFeature({ feature }: { feature: string }) {
   180→  return (
   181→    <InlineStack gap="200" blockAlign="start" wrap={false}>
   182→      <Box>
   183→        <Icon source={CheckCircleIcon} tone="success" />
   184→      </Box>
   185→      <Text as="span" variant="bodyMd">
   186→        {feature}
   187→      </Text>
   188→    </InlineStack>
   189→  );
   190→}
   191→
   192→// ─── Plan card ────────────────────────────────────────────────────────────────
   193→
   194→type PlanCardProps = {
   195→  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
   196→  isAnnual: boolean;
   197→  currentTier: string;
   198→  onSubscribe: (planName: string) => void;
   199→  onRequestCancel: () => void;
   200→  loadingPlan: string | null;
   201→};
   202→
   203→function PlanCard({
   204→  plan,
   205→  isAnnual,
   206→  currentTier,
   207→  onSubscribe,
   208→  onRequestCancel,
   209→  loadingPlan,
   210→}: PlanCardProps) {
   211→  const isCurrent = currentTier === plan.id;
   212→  const isBestValue = "bestValue" in plan && plan.bestValue;
   213→  const isCurrentPaid = currentTier !== "free";
   214→  const isDowngradeToFree = plan.id === "free" && isCurrentPaid;
   215→
   216→  // Tier order for upgrade/downgrade detection
   217→  const TIER_ORDER: Record<string, number> = { free: 0, pro: 1, ultimate: 2 };
   218→  const isUpgrade =
   219→    !isCurrent &&
   220→    plan.id !== "free" &&
   221→    (TIER_ORDER[plan.id] ?? 0) > (TIER_ORDER[currentTier] ?? 0);
   222→
   223→  const shopifyPlan = isAnnual
   224→    ? plan.shopifyPlanAnnual
   225→    : plan.shopifyPlanMonthly;
   226→
   227→  const displayPrice = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;
   228→
   229→  let buttonContent = "Start 14-day free trial";
   230→  if (isCurrent) {
   231→    buttonContent = "Current plan";
   232→  } else if (isDowngradeToFree) {
   233→    buttonContent = "Downgrade to Free";
   234→  } else if (isUpgrade) {
   235→    buttonContent = `Upgrade to ${plan.name}`;
   236→  } else if (!isCurrent && plan.id !== "free" && isCurrentPaid) {
   237→    // Paid → lower paid (e.g. Ultimate → Pro)
   238→    buttonContent = `Switch to ${plan.name}`;
   239→  }
   240→
   241→  const handleClick = () => {
   242→    if (isCurrent) return;
   243→    if (isDowngradeToFree) {
   244→      // Only cancellation flow (loses all paid features → needs confirmation)
   245→      onRequestCancel();
   246→    } else if (shopifyPlan) {
   247→      // All paid plan changes (upgrade or paid-to-paid switch) go via billing.request
   248→      onSubscribe(shopifyPlan);
   249→    }
   250→  };
   251→
   252→  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");
   253→
   254→  return (
   255→    <Card>
   256→      <BlockStack gap="400">
   257→
   258→        {/* Plan name + badges */}
   259→        <BlockStack gap="100">
   260→          <InlineStack align="space-between" blockAlign="center">
   261→            <Text as="h3" variant="headingMd" fontWeight="bold">
   262→              {plan.name}
   263→            </Text>
   264→            <InlineStack gap="150">
   265→              {isBestValue && (
   266→                <Badge tone="info" icon={StarIcon}>
   267→                  Most popular
   268→                </Badge>
   269→              )}
   270→              {isCurrent && <Badge tone="success">Active</Badge>}
   271→            </InlineStack>
   272→          </InlineStack>
   273→          <Text as="p" variant="bodySm" tone="subdued">
   274→            {plan.description}
   275→          </Text>
   276→        </BlockStack>
   277→
   278→        <Divider />
   279→
   280→        {/* Price */}
   281→        <BlockStack gap="100">
   282→          {plan.monthlyPrice === 0 ? (
   283→            <>
   284→              <Text as="p" variant="headingXl" fontWeight="bold">
   285→                Free
   286→              </Text>
   287→              <Text as="p" variant="bodySm" tone="subdued">
   288→                forever
   289→              </Text>
   290→            </>
   291→          ) : (
   292→            <>
   293→              <InlineStack gap="100" blockAlign="baseline">
   294→                <Text as="p" variant="headingXl" fontWeight="bold">
   295→                  ${displayPrice}
   296→                </Text>
   297→                <Text as="p" variant="bodySm" tone="subdued">
   298→                  / month
   299→                </Text>
   300→              </InlineStack>
   301→              <Text as="p" variant="bodySm" tone="subdued">
   302→                {isAnnual
   303→                  ? `billed $${plan.annualPrice} / year`
   304→                  : `or $${plan.annualMonthlyPrice}/mo billed annually`}
   305→              </Text>
   306→            </>
   307→          )}
   308→        </BlockStack>
   309→
   310→        {/* CTA button */}
   311→        <Button
   312→          variant={isCurrent ? "secondary" : "primary"}
   313→          tone={isDowngradeToFree ? "critical" : undefined}
   314→          onClick={handleClick}
   315→          disabled={isCurrent}
   316→          loading={isThisLoading}
   317→          fullWidth
   318→        >
   319→          {buttonContent}
   320→        </Button>
   321→
   322→        <Divider />
   323→
   324→        {/* Features list */}
   325→        <BlockStack gap="300">
   326→          {plan.features.map((f) => (
   327→            <PlanFeature key={f} feature={f} />
   328→          ))}
   329→        </BlockStack>
   330→
   331→      </BlockStack>
   332→    </Card>
   333→  );
   334→}
   335→
   336→// ─── Page ─────────────────────────────────────────────────────────────────────
   337→
   338→export default function PricingPage() {
   339→  const { subscription } = useLoaderData<typeof loader>();
   340→  const fetcher = useFetcher<typeof action>();
   341→  const shopify = useAppBridge();
   342→
   343→  const [isAnnual, setIsAnnual] = useState(
   344→    subscription.billingInterval === "annual",
   345→  );
   346→  const [loadingPlan, setLoadingPlan] = useState<string | null>(null);
   347→  const [cancelModalOpen, setCancelModalOpen] = useState(false);
   348→
   349→  const data = fetcher.data;
   350→  const isFetching = fetcher.state !== "idle";
   351→
   352→  // Redirect to Shopify billing confirmation page
   353→  useEffect(() => {
   354→    if (data && "confirmationUrl" in data && data.confirmationUrl) {
   355→      window.open(data.confirmationUrl as string, "_top");
   356→    }
   357→  }, [data]);
   358→
   359→  // Toast notifications + clear loading state
   360→  useEffect(() => {
   361→    if (!isFetching) setLoadingPlan(null);
   362→    if (data && "message" in data && data.message) {
   363→      shopify.toast.show(data.message as string);
   364→    }
   365→    if (data && "error" in data && data.error) {
   366→      shopify.toast.show(data.error as string, { isError: true });
   367→    }
   368→  }, [data, isFetching, shopify]);
   369→
   370→  const handleSubscribe = useCallback(
   371→    (planName: string) => {
   372→      setLoadingPlan(planName);
   373→      const fd = new FormData();
   374→      fd.set("intent", "subscribe");
   375→      fd.set("plan", planName);
   376→      fetcher.submit(fd, { method: "POST" });
   377→    },
   378→    [fetcher],
   379→  );
   380→
   381→  const handleConfirmCancel = useCallback(() => {
   382→    setCancelModalOpen(false);
   383→    setLoadingPlan("cancel");
   384→    const fd = new FormData();
   385→    fd.set("intent", "cancel");
   386→    fetcher.submit(fd, { method: "POST" });
   387→  }, [fetcher]);
   388→
   389→  const currentTier = subscription.planTier;
   390→  const currentPlanName =
   391→    PLANS_DATA[currentTier as keyof typeof PLANS_DATA]?.name ?? "Free";
   392→
   393→  return (
   394→    <Page
   395→      title="Pricing"
   396→      subtitle="Choose the plan that's right for your store"
   397→      backAction={{ url: "/app" }}
   398→    >
   399→      <Box paddingBlockEnd="1600">
   400→      <Layout>
   401→        <Layout.Section>
   402→          <BlockStack gap="600">
   403→
   404→            {/* Current plan status */}
   405→            {currentTier === "free" ? (
   406→              <Banner
   407→                tone="info"
   408→                title="You're on the Free plan"
   409→                action={{
   410→                  content: "Upgrade to Pro",
   411→                  onAction: () => {
   412→                    const plan = isAnnual
   413→                      ? PLANS_DATA.pro.shopifyPlanAnnual
   414→                      : PLANS_DATA.pro.shopifyPlanMonthly;
   415→                    if (plan) handleSubscribe(plan);
   416→                  },
   417→                }}
   418→              >
   419→                <Text as="p" variant="bodyMd">
