   148→   148→// Helper: sync widget config to an App Installation metafield so the
   149→   149→// storefront Liquid block can read it via app.metafields.zip_checker.widget_config.value
   150→   150→//
   151→   151→// IMPORTANT: ownerId MUST be the App Installation GID (not the Shop GID).
   152→   152→// app.metafields in Liquid only surfaces metafields owned by the App Installation.
   153→   153→// Using the Shop GID writes to shop metafields which are invisible to app.metafields.
   154→   154→async function syncConfigMetafield(
   155→   155→  admin: Awaited<ReturnType<typeof authenticate.admin>>["admin"],
   156→   156→  configData: Record<string, unknown>,
   157→   157→) {
   158→   158→  try {
   159→   159→    // Step 1: get the App Installation GID
   160→   160→    const installResponse = await admin.graphql(
   161→   161→      `query { currentAppInstallation { id } }`,
   162→   162→    );
   163→   163→    const installJson = (await installResponse.json()) as {
   164→   164→      data: { currentAppInstallation: { id: string } };
   165→   165→    };
   166→   166→    const appInstallationGid = installJson.data.currentAppInstallation.id;
   167→   167→
   168→   168→    // Step 2: write the metafield to the App Installation
   169→   169→    // Namespace must be plain "zip_checker" (no "$app:" prefix) for App Installation metafields.
   170→   170→    // The Liquid block reads: app.metafields.zip_checker.widget_config.value
   171→   171→    const metaResponse = await admin.graphql(
   172→   172→      `mutation MetafieldsSet($metafields: [MetafieldsSetInput!]!) {
   173→   173→        metafieldsSet(metafields: $metafields) {
   174→   174→          metafields { id namespace key }
   175→   175→          userErrors { field message }
   176→   176→        }
   177→   177→      }`,
   178→   178→      {
   179→   179→        variables: {
   180→   180→          metafields: [
   181→   181→            {
   182→   182→              ownerId: appInstallationGid,
   183→   183→              namespace: "zip_checker",
   184→   184→              key: "widget_config",
   185→   185→              type: "json",
   186→   186→              value: JSON.stringify(configData),
   187→   187→            },
   188→   188→          ],
   189→   189→        },
   190→   190→      },
   191→   191→    );
   192→   192→    const metaJson = (await metaResponse.json()) as {
   193→   193→      data: {
   194→   194→        metafieldsSet: {
   195→   195→          metafields: { id: string; namespace: string; key: string }[];
   196→   196→          userErrors: { field: string; message: string }[];
   197→   197→        };
   198→   198→      };
   199→   199→    };
