   189→   189→        },
   190→   190→      },
   191→   191→    );
   192→   192→    const metaJson = (await metaResponse.json()) as {
   193→   193→      data: {
   194→   194→        metafieldsSet: {
   195→   195→          metafields: { id: string; namespace: string; key: string }[];
   196→   196→          userErrors: { field: string; message: string }[];
   197→   197→        };
   198→   198→      };
   199→   199→    };
   200→   200→
   201→   201→    if (metaJson.data.metafieldsSet.userErrors.length > 0) {
